import pytest
import click
from click.testing import CliRunner
from click.types import FuncParamType

class MyClass:
    def __init__(self, myvalue: str):
        self.myvalue = myvalue

    @staticmethod
    def from_str(input_str: str) -> "MyClass":
        if input_str != "works":
            raise ValueError(f"input was {input_str!r}, should be 'works'")
        return MyClass(input_str)

@click.command()
@click.argument("mydata", type=FuncParamType(MyClass.from_str))
def cli(mydata):
    click.echo(f"MyData: {mydata.myvalue}")

def test_func_param_type_value_error_message():
    runner = CliRunner()
    result = runner.invoke(cli, ["fails"])
    assert result.exit_code == 2
    # The bug is that it currently outputs "Error: Invalid value for 'MYDATA': fails"
    # It should output the message from the ValueError
    assert "Error: Invalid value for 'MYDATA': input was 'fails', should be 'works'" in result.output
